import type { On } from "claude-code";
import {
  onCheck as h0,
  onDismiss as h1,
  onHeadsUp as h2,
  onHeadsUpContext as h3,
  onRender as h4,
  onTurnStart as h5,
} from "../slices/notice/adapters/mod.ts";

export const register = (on: On): void => {
  // eval: tool.call notice
  on("tool.call", h3);
  // eval: tool.check notice
  on("tool.check", { tool: ["Edit", "Write", "NotebookEdit", "Bash"] }, h0);
  // eval: turn.start notice
  on("turn.start", h5);
  // eval: ui.press notice
  on(
    "ui.press",
    { plugin: "dcc-plugin-you-should-know", element: "dismiss" },
    h1,
  );
  // eval: ui.press notice
  on(
    "ui.press",
    { plugin: "dcc-plugin-you-should-know", element: "heads_up" },
    h2,
  );
  // eval: ui.render notice
  on("ui.render", { component: "AbovePrompt" }, h4);
